TR["lo"] = ("ສວນດອກໄມ້ດາລັດ: 9 ສວນ ແລະທົ່ງດອກໄມ້ ເວລາເປີດ ແລະເສັ້ນທາງ | Van Phu",
 "ສວນດອກໄມ້ ແລະທົ່ງດອກໄມ້ໃນດາລັດ",
 "ສວນດອກໄມ້ ແລະທົ່ງດອກໄມ້ 9 ແຫ່ງໃນດາລັດ: ສວນດອກໄມ້ໃນເມືອງ ທົ່ງໄຮເດຣນເຈຍ ແລະລາເວນເດີ ສວນແບບເອີຣົບ — ເວລາເປີດຈາກ Google Maps ລາຄາປີ້ໂດຍປະມານ ແລະເສັ້ນທາງ.",
 "9 ສວນ ແລະທົ່ງດອກໄມ້ທີ່ນັກທ່ອງທ່ຽວມັກໃສ່ໃນແຜນດາລັດ ຕັ້ງແຕ່ສວນດອກໄມ້ໃນເມືອງທີ່ໜອງ Xuân Hương ຮອດທົ່ງໄຮເດຣນເຈຍ ແລະລາເວນເດີ. ສວນໃນເມືອງ ແລະ Fresh Garden ຢູ່ໃກ້ໃຈກາງເມືອງ; ສວນເອີຣົບ, The Florest ແລະ Gods' Valley ໄກກວ່າ ຈຶ່ງຄວນຂີ່ມໍເຕີໄຊເກຍທຳມະດາ.",
 "ສວນ (1–9)", "ເວລາທີ່ດີທີ່ສຸດ",
 [("ເມສາ–ສິງຫາ", "ໄຮເດຣນເຈຍ ແລະລາເວນເດີບານສວຍທີ່ສຸດ"), ("ຕອນເຊົ້າ (6:30–9:00)", "ໝອກ ແລະແສງອ່ອນເໝາະກັບການຖ່າຍຮູບ"), ("ແລງ (15:00–17:00)", "ແສງແດດອ່ອນ ແລະນັກທ່ອງທ່ຽວໜ້ອຍກວ່າ"), ("ສຸດອາທິດ", "ສວນແອອັດ ອາດຕິດຂັດ")],
 "ຄວນຮູ້",
 ["ລາຄາເປັນລາຄາປະມານຈາກຄວາມເຫັນຂອງນັກທ່ອງທ່ຽວຫຼ້າສຸດ — ກວດຄືນທີ່ປະຕູ.",
  "ສວນເອີຣົບທີ່ກາວດັດ ແລະ The Florest ຢູ່ໄກ ແລະມີເສັ້ນທາງຫີນກວດບາງຊ່ວງ — ຄວນຂີ່ມໍເຕີໄຊເກຍທຳມະດາ ຫຼືເຊົ່າລົດ.",
  "ທີ່ Dalat Gods' Valley ແລະ Lavender Dalat ໃຫ້ຄົນຂັບລໍຖ້າ ເພາະແທັກຊີມີໜ້ອຍ.",
  "ຄວນໄປສວນໃນເມືອງຕອນເຊົ້າ ເພາະຕອນທ່ຽງແດດແຮງ ແລະຄົນຫຼາຍ."],
 [("ສວນດອກໄມ້ໃນເມືອງດາລັດ", "ຕອນເຊົ້າ", "ດອກໄມ້ຫຼາຍຮ້ອຍຊະນິດຢູ່ໜອງ Xuân Hương ມີເຮືອນແກ້ວດອກກຸຫຼາບ ແລະສວນບອນໄຊຢູ່ດ້ານຫຼັງ; ຄ່າເຂົ້າປະມານ 100,000 ດົງ."),
  ("ທີ່ສູງດອກໄມ້ດາລັດ", "ຕອນເຊົ້າ", "ສວນໃນປ່າສົນ ມີສວນກຸຫຼາບ ຕົ້ນໄທຣ໌ໂບຣານ ແລະເນີນໄຮເດຣນເຈຍ; ຊິງຊ້າສູງເບິ່ງເຫັນດ່ານ Tà Nung."),
  ("Fresh Garden", "ຕອນເຊົ້າ", "ສວນລາເວນເດີ ດອກເບຍເສີ ແລະມອນສະເຕຣາ ທີ່ໝູ່ບ້ານດອກໄມ້ Vạn Thành ມີກັງຫັນລົມ ແລະສວນສັດນ້ອຍ; ປີ້ລວມເຄື່ອງດື່ມ 1 ແກ້ວ."),
  ("ສວນເອີຣົບ Cầu Đất", "ຕອນເຊົ້າ", "ສວນແບບເອີຣົບມີກັງຫັນລົມ ແລະຮ້ານກາເຟໃນຕູ້ລົດໄຟ; ຕາມຄວາມເຫັນ ປີ້ປະມານ 90,000 ດົງລວມເຄື່ອງດື່ມ."),
  ("The Florest – Hoa Trong Rừng", "ຕອນເຊົ້າ", "ສວນດອກໄມ້ 60 ເຮັກຕາໃນປ່າສົນທີ່ Cam Ly ມີເນີນດອກໄມ້ ລຳທານ ແລະທົ່ງອໍ້; ຕາມຄວາມເຫັນ ປີ້ປະມານ 210,000 ດົງ."),
  ("Dalat Fairytale Land", "ຕອນເຊົ້າ", "ໝູ່ບ້ານແບບ Hobbit ທ່າມກາງສວນດອກໄມ້ ມີເຮືອນໄມ້; ປີ້ລວມຫ້ອງເກັບໄວນ໌ Vĩnh Tiến."),
  ("ຮ່ອມພູເທບ (GOD Valley)", "ຕອນເຊົ້າ", "ຮ່ອມພູແບບນິທານທີ່ມີຮູບປັ້ນໃຫຍ່ທີ່ເຄື່ອນໄຫວໄດ້; ຕາມຄວາມເຫັນ ປີ້ 150,000–220,000 ດົງ ຕາມອາຫານທີ່ລວມ."),
  ("ທົ່ງໄຮເດຣນເຈຍ Trại Mát", "ຕອນເຊົ້າ ຫຼືແລງ", "ທົ່ງໄຮເດຣນເຈຍຫ່າງຈາກໃຈກາງເມືອງປະມານ 8 ກມ ມີສະພານໄມ້ຂ້າມເນີນດອກໄມ້; ຄ່າເຂົ້າປະມານ 80,000 ດົງລວມເຄື່ອງດື່ມ."),
  ("ທົ່ງລາເວນເດີ Hồ Tuyền Lâm", "ຕອນເຊົ້າ ຫຼືແລງ", "ທົ່ງລາເວນເດີຂ້າງໜອງ Tuyền Lâm ມີລົດຄອສເຕີລົງເນີນ; ຄ່າເຂົ້າປະມານ 80,000 ດົງ ແພັກເກັດລວມເຄື່ອງດື່ມ 150,000 ດົງ.")])

TR["my"] = ("ဒလတ်ရှိ ပန်းခြံများ — နေရာ ၉ ခု၊ ဖွင့်ချိန်နှင့် လမ်းညွှန် | Van Phu",
 "ဒလတ်ရှိ ပန်းခြံနှင့် ပန်းကွင်းများ",
 "ဒလတ်ရှိ ပန်းခြံနှင့် ပန်းကွင်း ၉ ခု — မြို့ပန်းခြံ၊ ဟိုက်ဒရိန်ဂျီယာနှင့် လက်ဗန်းဒါကွင်း၊ ဥရောပပုံစံ ဥယျာဉ်။ Google Maps ဖွင့်ချိန်၊ ခန့်မှန်းဈေးနှုန်းနှင့် လမ်းညွှန်။",
 "ခရီးသွားများ ဒလတ်ခရီးစဉ်တွင် ထည့်သွင်းလေ့ရှိသော ပန်းခြံ နှင့် ပန်းကွင်း ၉ ခု — ဆူအန်ဟွန်ရေကန်ကမ်းခြေရှိ မြို့ပန်းခြံမှ ဟိုက်ဒရိန်ဂျီယာနှင့် လက်ဗန်းဒါကွင်းများအထိ။ မြို့ပန်းခြံနှင့် Fresh Garden သည် မြို့လယ်နှင့် နီးသည်; ဥရောပပုံစံ ဥယျာဉ်၊ The Florest နှင့် Gods' Valley တို့ ပိုဝေးသဖြင့် ဂီယာသုံးမော်တော်ဆိုင်ကယ် သင့်တော်သည်။",
 "ပန်းခြံ (၁–၉)", "သွားရောက်ရန် အကောင်းဆုံးအချိန်",
 [("ဧပြီ–သြဂုတ်", "ဟိုက်ဒရိန်ဂျီယာနှင့် လက်ဗန်းဒါ အပွင့်အလှဆုံး"), ("နံနက်စော (၆:၃၀–၉:၀၀)", "မြူနှင့် နူးညံ့သော အလင်းသည် ဓာတ်ပုံအတွက် ကောင်းသည်"), ("နေ့လည်ပိုင်း (၁၅:၀၀–၁၇:၀၀)", "နေရောင်ပျော့ပြီး ခရီးသည်နည်းသည်"), ("စနေ၊ တနင်္ဂနွေ", "ပန်းခြံများ လူများပြီး ယာဉ်ကြပ်နိုင်သည်")],
 "သိထားသင့်သည်များ",
 ["ဈေးနှုန်းများသည် မကြာသေးမီက သုံးသပ်ချက်များအပေါ် အခြေခံ၍ ခန့်မှန်းထားခြင်းဖြစ်သည် — ဝင်ပေါက်တွင် စစ်ဆေးပါ။",
  "Cầu Đất ရှိ ဥရောပပုံစံ ဥယျာဉ်နှင့် The Florest သည် ပိုဝေးပြီး ကျောက်စရစ်လမ်းအချို့ ရှိသည် — ဂီယာသုံးမော်တော်ဆိုင်ကယ် သို့မဟုတ် ကားငှားပါ။",
  "Dalat Gods' Valley နှင့် Lavender Dalat တွင် ကားမောင်းသူကို စောင့်ခိုင်းပါ၊ တက္ကစီ နည်းသည်။",
  "မြို့ပန်းခြံကို နံနက်စောစော သွားပါ၊ နေ့လည်တွင် နေပူပြီး လူများသည်။"],
 [("ဒလတ်မြို့ပန်းခြံ", "နံနက်စော", "ဆူအန်ဟွန်ရေကန်ကမ်းခြေတွင် ပန်းမျိုးစုံ၊ နောက်ဘက်တွင် နှင်းဆီဟော်တိုက်နှင့် ဘောဒိုင်ခြံ ရှိသည်; ဝင်ခွင့် ၁၀၀,၀၀၀ ဒေါင်ခန့်။"),
  ("ဒလတ်ပန်းမြင့်ပြင်", "နံနက်", "လင်းပိုင်းတော်အတွင်း ဥယျာဉ် — နှင်းဆီခင်း၊ သစ်ဟောင်းဘုတ်ပင်နှင့် ဟိုက်ဒရိန်ဂျီယာတောင်ကုန်းများ; Tà Nung ကြမ်းပါးမှ မြင်ရသော အမြင့်ပျံလှေ။"),
  ("Fresh Garden", "နံနက်", "ဗန်သန်ပန်းရွာရှိ လက်ဗန်းဒါ၊ ကြာဖူးနှင့် မွန်စတီရာ ဥယျာဉ်များ၊ လေအားစက်ဘီးနှင့် သားရဲငယ်ဥယျာဉ်ရှိသည်; လက်မှတ်တွင် ဖျော်ရည် ၁ ခွက်ပါသည်။"),
  ("Cầu Đất ဥရောပဥယျာဉ်", "နံနက်", "လေအားစက်ဘီးနှင့် ရထားဘောဂီအတွင်းကော်ဖီဆိုင်ပါသော ဥရောပပုံစံဥယျာဉ်; သုံးသပ်ချက်အရ ဝင်ခွင့် ၉၀,၀၀၀ ဒေါင်ခန့် ဖျော်ရည်ပါ။"),
  ("The Florest – Hoa Trong Rừng", "နံနက်", "ကမ်လီ ရှိ စနှင့်တောအတွင်း ဟက်တာ ၆၀ ပန်းဥယျာဉ် — ပန်းတောင်ကုန်း၊ စီးကြောင်းနှင့် ကောက်ရိုးကွင်း; သုံးသပ်ချက်အရ ဝင်ခွင့် ၂၁၀,၀၀၀ ဒေါင်ခန့်။"),
  ("Dalat Fairytale Land", "နံနက်", "ပန်းခြံများကြားရှိ ဟော်ဘစ်ပုံစံ ရွာ၊ သစ်ပြားအိမ်များ; လက်မှတ်တွင် Vĩnh Tiến ဝိုင်ခန်းပါသည်။"),
  ("ဒလတ် နတ်ဘုရားချိုင့် (GOD Valley)", "နံနက်", "ဒဏ္ဍာရီဆိုင်ရာ ချိုင့်ဝှမ်း၊ လှုပ်ရှားနိုင်သော ကြီးမားသည့် ရုပ်တုများ; သုံးသပ်ချက်အရ လက်မှတ် ၁၅၀,၀၀၀–၂၂၀,၀၀၀ ဒေါင်၊ အစားအစာပါမပါပေါ် မူတည်သည်။"),
  ("Trại Mát ဟိုက်ဒရိန်ဂျီယာခင်း", "နံနက်စော သို့မဟုတ် နေ့လည်", "မြို့လယ်မှ ၈ ကီလိုမီတာခန့် ဟိုက်ဒရိန်ဂျီယာခင်း၊ ပန်းတောင်ကုန်းပေါ်တွင် သစ်တံတားရှိသည်; ဝင်ခွင့် ၈၀,၀၀၀ ဒေါင်ခန့် ဖျော်ရည်ပါ။"),
  ("Tuyền Lâm ရေကန် လက်ဗန်းဒါခင်း", "နံနက် သို့မဟုတ် နေ့လည်", "Tuyền Lâm ရေကန်ဘေးရှိ လက်ဗန်းဒါခင်း၊ တောင်ကုန်းမှ ကိုယ့်ဘာသာ ဆင်းသော ကိုစတာ စီးနိုင်သည်; ဝင်ခွင့် ၈၀,၀၀၀ ဒေါင်ခန့်၊ ဖျော်ရည်ပါပက်ကေ့ ၁၅၀,၀၀၀ ဒေါင်။")])
